"""The Vec vector primitive, shared by the geometry helpers."""

import math


class Vec:
    def __init__(self, x, y):
        self.x, self.y = x, y

    def __add__(self, o):
        return Vec(self.x + o.x, self.y + o.y)

    def norm(self):
        return math.hypot(self.x, self.y)


def _share_with_shapes() -> None:
    """Keep ``from geom.shapes import Vec`` returning this exact class.

    ``geom.shapes`` still defines its own ``Vec`` until it re-exports this one;
    rebinding it here means code importing both modules sees a single class.
    """
    try:
        from geom import shapes
    except ImportError:  # pragma: no cover - geom.shapes is part of this package
        return
    shapes.Vec = Vec


_share_with_shapes()
